# Lennard-Jones molecular dynamics, LNS table add/sub (generated by gen_md.py)
# N=27, dt=0.005, steps=200, log every 5 steps. Log at 'log': KE, PE, E, 81 positions
#   as raw LNS words. pos/vel are converted to LNS in place at start-up.
# L registers: ls0 dt/2, ls1 dt, ls2 24, ls3 48, ls4 4, ls5 0.5, ls6-ls8 xi,
#   ls9-ls11 Fi, la1 PE, la0 E (final), lt0-lt10 temporaries.
# x registers s10 = -3, s11 = -1 (lpown exponents).
.data
dt:      .float 0.005
nsteps:  .word 200
logint:  .word 5
pos:     .float 1.0042, 1.0345, 1.00755
         .float 1.00955, 1.00875, 2.1483
         .float 1.0189, 1.04275, 3.19015
         .float 1.01495, 2.07235, 0.95775
         .float 0.9989, 2.15145, 2.10975
         .float 0.961, 2.08595, 3.2162
         .float 1.00945, 3.20965, 0.9518
         .float 1.0345, 3.271, 2.1041
         .float 0.98275, 3.23505, 3.26665
         .float 2.14925, 0.9822, 1.03405
         .float 2.1427, 1.02455, 2.12615
         .float 2.07135, 1.0302, 3.2806
         .float 2.08945, 2.12665, 1.0487
         .float 2.16025, 2.1081, 2.13405
         .float 2.12335, 2.10465, 3.2876
         .float 2.089, 3.2778, 1.03415
         .float 2.0757, 3.26015, 2.14785
         .float 2.09295, 3.26355, 3.26185
         .float 3.1906, 0.9834, 1.01955
         .float 3.27875, 0.97855, 2.09825
         .float 3.24405, 0.98795, 3.25575
         .float 3.19835, 2.09655, 1.0073
         .float 3.22015, 2.1659, 2.14955
         .float 3.20785, 2.15195, 3.21645
         .float 3.21555, 3.2848, 1.01365
         .float 3.22115, 3.23125, 2.13425
         .float 3.1976, 3.2052, 3.25095
vel:     .float 0.30935633, 0.34487042, 0.169662
         .float -0.09036689, -0.5155025, -0.10422245
         .float -0.5242545, 0.23098916, 0.43443593
         .float 0.4124189, -0.23022996, -0.3257215
         .float -0.5891668, -0.39478838, -0.10706948
         .float -0.2270244, -0.31108564, 0.46518388
         .float 0.2968294, 0.4775421, -0.092834316
         .float 0.029777842, 0.36252204, 0.21806154
         .float -0.31186596, 0.072694205, 0.040976167
         .float 0.2951212, 0.36650786, -0.21867311
         .float 0.34409013, -0.1983432, -0.56771916
         .float 0.38508737, -0.506392, -0.22265896
         .float 0.30252346, 0.28565216, 0.027879821
         .float -0.37393123, 0.03226636, 0.08368164
         .float -0.33805865, 0.14102297, 0.22261678
         .float -0.13534999, 0.25604305, -0.095111944
         .float -0.05961895, 0.41262978, -0.22949183
         .float -0.11485136, 0.14899465, -0.19418864
         .float -0.35571024, -0.5075308, 0.010797631
         .float 0.11404998, -0.025813086, 0.08994511
         .float 0.17896229, 0.56295305, 0.3404839
         .float 0.41925177, -0.05029756, 0.12638712
         .float -0.15641803, -0.20631489, -0.18052289
         .float -0.45478693, -0.2336464, 0.29891723
         .float 0.5052321, -0.50012857, -0.38664797
         .float -0.16040386, -0.28090712, -0.33881783
         .float 0.29910704, 0.26629236, 0.53465146
frc:     .zero 324
log:     .zero 13776                # 41 samples x 84 words
.text
    la s0, pos
    la s1, vel
    la s2, frc
    la s3, log
    li s4, 27                  # N
    li s8, 81                  # 3N
# convert pos and vel (2 x 3N words, contiguous) to LNS in place
    mv t0, s0
    li t1, 162
cvt_loop:
    flw f0, 0(t0)
    fcvt.lns.s lt0, f0
    lsw lt0, 0(t0)
    addi t0, t0, 4
    addi t1, t1, -1
    bnez t1, cvt_loop
    li s10, -3
    li s11, -1
    li t0, 2
    fcvt.lns.w lt0, t0         # 2
    lpown ls5, lt0, s11        # 0.5 = 2^-1 (exact)
    li t0, 24
    fcvt.lns.w ls2, t0         # 24
    li t0, 48
    fcvt.lns.w ls3, t0         # 48
    li t0, 4
    fcvt.lns.w ls4, t0         # 4
    la t0, dt
    flw f0, 0(t0)
    fcvt.lns.s ls1, f0         # dt
    lmul  ls0, ls5, ls1        # h = 0.5*dt (exact)
    la t0, nsteps
    lw s6, 0(t0)               # steps
    la t0, logint
    lw s9, 0(t0)               # log interval
    mv s7, s9
    li s5, 1                   # PE needed for sample 0
    jal ra, force
    jal ra, logsample
    beqz s6, done
step_loop:
    jal ra, kick               # v += h*F
    jal ra, drift              # x += dt*v
    addi s7, s7, -1
    seqz s5, s7                # log step?
    jal ra, force
    jal ra, kick
    beqz s5, no_log
    jal ra, logsample
    mv s7, s9
no_log:
    addi s6, s6, -1
    bnez s6, step_loop
done:
    fcvt.s.lns f10, la0        # final E, also as FP32 in f10
    li a0, 0
    li a7, 10                  # exit
    ecall

# ---- force: F = sum of pair forces; PE accumulated when s5 != 0 ----
force:
    mv t0, s2
    mv t1, s8
fz_loop:
    lsw lzero, 0(t0)           # F = 0
    addi t0, t0, 4
    addi t1, t1, -1
    bnez t1, fz_loop
    ladd  la1, lzero, lzero     # PE = 0
    li t1, 0                   # i
    mv t3, s0                  # &pos[i]
    mv a2, s2                  # &frc[i]
fi_loop:
    llw ls6, 0(t3)
    llw ls7, 4(t3)
    llw ls8, 8(t3)
    ladd  ls9, lzero, lzero     # Fi = 0
    ladd  ls10, lzero, lzero
    ladd  ls11, lzero, lzero
    addi t2, t1, 1             # j = i + 1
    addi t4, t3, 12            # &pos[j]
    addi a3, a2, 12            # &frc[j]
    bge t2, s4, fi_store
fj_loop:
    llw lt0, 0(t4)
    llw lt1, 4(t4)
    llw lt2, 8(t4)
    lsub  lt0, ls6, lt0         # dx
    lsub  lt1, ls7, lt1         # dy
    lsub  lt2, ls8, lt2         # dz
    lmul  lt3, lt0, lt0
    lmul  lt4, lt1, lt1
    ladd  lt3, lt3, lt4
    lmul  lt4, lt2, lt2
    ladd  lt3, lt3, lt4         # r2
    lpown lt4, lt3, s11        # inv2 = r2^-1
    lpown lt5, lt3, s10        # s6 = r2^-3
    lmul  lt6, lt5, lt5        # s12
    lmul  lt7, ls3, lt6        # 48*s12
    lmul  lt8, ls2, lt5        # 24*s6
    lsub  lt7, lt7, lt8
    lmul  lt7, lt7, lt4        # f = (48*s12 - 24*s6)*inv2
    lmul  lt0, lt7, lt0        # fx
    lmul  lt1, lt7, lt1        # fy
    lmul  lt2, lt7, lt2        # fz
    ladd  ls9, ls9, lt0         # Fi += f*d
    ladd  ls10, ls10, lt1
    ladd  ls11, ls11, lt2
    llw lt3, 0(a3)             # Fj -= f*d
    lsub  lt3, lt3, lt0
    lsw lt3, 0(a3)
    llw lt3, 4(a3)
    lsub  lt3, lt3, lt1
    lsw lt3, 4(a3)
    llw lt3, 8(a3)
    lsub  lt3, lt3, lt2
    lsw lt3, 8(a3)
    beqz s5, fj_next
    lsub  lt6, lt6, lt5         # s12 - s6
    lmul  lt6, ls4, lt6        # 4*(s12 - s6)
    ladd  la1, la1, lt6         # PE +=
fj_next:
    addi t2, t2, 1
    addi t4, t4, 12
    addi a3, a3, 12
    blt t2, s4, fj_loop
fi_store:
    llw lt3, 0(a2)             # F[i] += Fi
    ladd  lt3, lt3, ls9
    lsw lt3, 0(a2)
    llw lt3, 4(a2)
    ladd  lt3, lt3, ls10
    lsw lt3, 4(a2)
    llw lt3, 8(a2)
    ladd  lt3, lt3, ls11
    lsw lt3, 8(a2)
    addi t1, t1, 1
    addi t3, t3, 12
    addi a2, a2, 12
    blt t1, s4, fi_loop
    ret

# ---- kick: v += h*F (all 3N components) ----
kick:
    mv t0, s1
    mv t1, s2
    mv t2, s8
kick_loop:
    llw lt0, 0(t0)
    llw lt1, 0(t1)
    lmul  lt1, ls0, lt1
    ladd  lt0, lt0, lt1
    lsw lt0, 0(t0)
    addi t0, t0, 4
    addi t1, t1, 4
    addi t2, t2, -1
    bnez t2, kick_loop
    ret

# ---- drift: x += dt*v ----
drift:
    mv t0, s0
    mv t1, s1
    mv t2, s8
drift_loop:
    llw lt0, 0(t0)
    llw lt1, 0(t1)
    lmul  lt1, ls1, lt1
    ladd  lt0, lt0, lt1
    lsw lt0, 0(t0)
    addi t0, t0, 4
    addi t1, t1, 4
    addi t2, t2, -1
    bnez t2, drift_loop
    ret

# ---- logsample: KE = 0.5*sum(v*v); store KE, PE, E and the positions ----
logsample:
    ladd  lt2, lzero, lzero     # sum = 0
    mv t0, s1
    mv t2, s8
ke_loop:
    llw lt1, 0(t0)
    lmul  lt1, lt1, lt1
    ladd  lt2, lt2, lt1
    addi t0, t0, 4
    addi t2, t2, -1
    bnez t2, ke_loop
    lmul  lt2, ls5, lt2        # KE
    ladd  la0, lt2, la1         # E = KE + PE
    lsw lt2, 0(s3)
    lsw la1, 4(s3)
    lsw la0, 8(s3)
    mv t0, s0
    addi t1, s3, 12
    mv t2, s8
copy_loop:
    lw t3, 0(t0)
    sw t3, 0(t1)
    addi t0, t0, 4
    addi t1, t1, 4
    addi t2, t2, -1
    bnez t2, copy_loop
    addi s3, s3, 336             # next record
    ret
